import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.Disclosure;
export type Model = Ui.Disclosure.Model;

export const { Closed, CompletedFocusButton, Message } = Ui.Disclosure;
export type Closed = Ui.Disclosure.Closed;
export type CompletedFocusButton = Ui.Disclosure.CompletedFocusButton;
export type Toggled = Ui.Disclosure.Toggled;
export type Message = Ui.Disclosure.Message;

export const { OutMessage, ToggledOpenState } = Ui.Disclosure;
export type OutMessage = Ui.Disclosure.OutMessage;
export type ToggledOpenState = Ui.Disclosure.ToggledOpenState;

export type InitConfig = Ui.Disclosure.InitConfig;
export type ViewInputs = Ui.Disclosure.ViewInputs;
export type DisclosureAttributes = Ui.Disclosure.DisclosureAttributes;
export type InitReturn = readonly [Model, readonly Command.Command<Message>[]];
export type UpdateReturn = ReturnType<typeof Ui.Disclosure.update>;

export const { FocusButton } = Ui.Disclosure;

export const init = (config: InitConfig): InitReturn => [
  Ui.Disclosure.init(config),
  [],
];

export const { close, reflectOpenState, toggle, update, view } = Ui.Disclosure;

export {
  buttonClassName,
  buttonContentClassName,
  chevronClassName,
  disclosureView,
  panelClassName,
  rootClassName,
} from "./view";
export type { DisclosureViewInput } from "./view";

import type { Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export const rootClassName = "max-w-md";

export const buttonClassName =
  "flex w-full cursor-pointer select-none items-center justify-between rounded-lg border border-gray-300 px-4 py-3 text-left text-base font-normal text-gray-900 transition hover:bg-gray-100 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 data-[open]:rounded-b-none";

export const panelClassName =
  "rounded-b-lg border-x border-b border-gray-300 px-4 py-3 text-sm text-gray-700";

export const buttonContentClassName =
  "flex w-full items-center justify-between gap-4";

export const chevronClassName =
  "text-sm text-gray-600 transition-transform group-data-[open]:rotate-180";

export type DisclosureViewInput = Readonly<{
  attributes: Ui.Disclosure.DisclosureAttributes;
  isOpen: boolean;
  title: string;
  body: string;
}>;

export const disclosureView = ({
  attributes,
  isOpen,
  title,
  body,
}: DisclosureViewInput): Html => {
  const h = html<Ui.Disclosure.Message>();

  return h.div(
    [h.Class(rootClassName)],
    [
      h.button(
        [
          ...attributes.button,
          h.AriaLabel(title),
          h.Class(`group ${buttonClassName}`),
        ],
        [
          h.span(
            [h.Class(buttonContentClassName)],
            [
              h.span([], [title]),
              h.span([h.AriaHidden(true), h.Class(chevronClassName)], ["v"]),
            ]
          ),
        ]
      ),
      isOpen
        ? h.div([...attributes.panel, h.Class(panelClassName)], [body])
        : h.empty,
    ]
  );
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Disclosure from "./index";

const GotDisclosureMessage = m("GotDisclosureMessage", {
  message: Disclosure.Message,
});

const Model = S.Struct({
  disclosure: Disclosure.Model,
  status: S.String,
});

type Model = typeof Model.Type;

const Message = S.Union([GotDisclosureMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  disclosure: Disclosure.init({ id: "registry-disclosure" })[0],
  status: "Closed",
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotDisclosureMessage: ({ message }) => {
        const [disclosure, commands, maybeOutMessage] = Disclosure.update(
          model.disclosure,
          message
        );

        const status = Option.match(maybeOutMessage, {
          onNone: () => model.status,
          onSome: M.type<Disclosure.OutMessage>().pipe(
            M.tagsExhaustive({
              ToggledOpenState: ({ isOpen }) => (isOpen ? "Open" : "Closed"),
            })
          ),
        });

        return [
          evo(model, {
            disclosure: () => disclosure,
            status: () => status,
          }),
          Command.mapMessages(commands, (message) =>
            GotDisclosureMessage({ message })
          ),
        ];
      },
    })
  );

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.disclosure.id,
        model: model.disclosure,
        view: Disclosure.view,
        viewInputs: {
          toView: (attributes) =>
            Disclosure.disclosureView({
              attributes,
              isOpen: model.disclosure.isOpen,
              title: "Registry disclosure",
              body: "Registry disclosure content.",
            }),
        },
        toParentMessage: (message) => GotDisclosureMessage({ message }),
      }),
      h.p([], [`Status: ${model.status}`]),
    ]
  );
});

describe("Disclosure registry view", () => {
  test("opens and closes with parent-visible OutMessage state", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.text("Status: Closed")).toExist(),
      Scene.click(Scene.role("button", { name: "Registry disclosure" })),
      Scene.expect(Scene.text("Status: Open")).toExist(),
      Scene.expect(Scene.text("Registry disclosure content.")).toExist(),
      Scene.click(Scene.role("button", { name: "Registry disclosure" })),
      Scene.Command.resolve(
        Disclosure.FocusButton({ id: "registry-disclosure" }),
        Disclosure.CompletedFocusButton(),
        (message) => GotDisclosureMessage({ message })
      ),
      Scene.expect(Scene.text("Status: Closed")).toExist(),
      Scene.expect(Scene.text("Registry disclosure content.")).not.toExist()
    );
  });
});
